const addSectionVisuals = item => {
  const visuals = sectionVisuals[item.id];
  if (!visuals || !item.sections) return item;
  return {...item,sections:item.sections.map((section,index)=>{
  const visual = visuals[index];
  if (!visual) return section;
  return Array.isArray(section) ? [section[0],section[1],section[2],section[3],visual] : {...section,visual};
  })};
};
